import { cookie,hash,isAdmin,sameOrigin,sessionToken } from '../../../../lib/admin-auth';
import { surveyDb } from '../../../../lib/survey-db';
const response=(body:unknown,status=200,headers:Record<string,string>={})=>Response.json(body,{status,headers:{'Cache-Control':'no-store',...headers}});
export async function GET(request:Request){try{return response({authenticated:await isAdmin(request)})}catch(e){console.error(e);return response({error:'ตรวจสอบการเข้าถึงไม่ได้ กรุณาลองอีกครั้ง'},503)}}
export async function POST(request:Request){
 if(!sameOrigin(request))return response({error:'ไม่อนุญาตคำขอนี้'},403);
 try{
 const now=Date.now(),db=surveyDb(),key=await hash(request.headers.get('x-vercel-forwarded-for')??request.headers.get('x-forwarded-for')?.split(',')[0]?.trim()??'local'),period=15*60*1000;
 const attempt=await db.prepare('SELECT count,window_start FROM pin_attempts WHERE key=?').bind(key).first<{count:number;window_start:number}>();
 if(attempt&&now-attempt.window_start<period&&attempt.count>=5)return response({error:'ใส่รหัสผิดหลายครั้ง กรุณารอ 15 นาทีแล้วลองใหม่'},429,{'Retry-After':String(Math.ceil((period-(now-attempt.window_start))/1000))});
 const body=await request.json() as {pin?:unknown};
 if(typeof body.pin!=='string'||await hash(body.pin)!==await hash(process.env.ADMIN_PIN??'4321')){
 await db.prepare('INSERT INTO pin_attempts (key,count,window_start) VALUES (?,1,?) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN pin_attempts.window_start<? THEN 1 ELSE pin_attempts.count+1 END,window_start=CASE WHEN pin_attempts.window_start<? THEN excluded.window_start ELSE pin_attempts.window_start END').bind(key,now,now-period,now-period).run();
 return response({error:'รหัสไม่ถูกต้อง กรุณาลองอีกครั้ง'},401);
 }
 const token=crypto.randomUUID();await db.batch([db.prepare('DELETE FROM pin_attempts WHERE key=?').bind(key),db.prepare('DELETE FROM admin_sessions WHERE expires_at<=?').bind(now),db.prepare('INSERT INTO admin_sessions (token_hash,expires_at) VALUES (?,?)').bind(await hash(token),now+8*60*60*1000)]);
 return response({authenticated:true},200,{'Set-Cookie':cookie(request,token,8*60*60)});
 }catch(e){console.error(e);return response({error:'ยังเข้าสู่หน้าสรุปไม่ได้ กรุณาลองอีกครั้ง'},503)}
}
export async function DELETE(request:Request){if(!sameOrigin(request))return response({error:'ไม่อนุญาตคำขอนี้'},403);try{const token=sessionToken(request);if(token)await surveyDb().prepare('DELETE FROM admin_sessions WHERE token_hash=?').bind(await hash(token)).run();return response({authenticated:false},200,{'Set-Cookie':cookie(request,'',0)})}catch(e){console.error(e);return response({error:'ออกจากหน้าสรุปไม่สำเร็จ กรุณาลองอีกครั้ง'},503)}}

import { isAdmin, unauthorized } from '../../../lib/admin-auth';
import { surveyDb } from '../../../lib/survey-db';
import { workbook } from '../../../lib/xlsx';
import { shirtSizes, type SurveyRow } from '../../../lib/survey';
export async function GET(request:Request){try{
 if(!await isAdmin(request))return unauthorized();
 const {results}=await surveyDb().prepare('SELECT id,employee_id,name,department,position,need,size,CASE WHEN need=1 THEN 1 ELSE 0 END AS quantity,created_at FROM responses ORDER BY created_at DESC').all<SurveyRow>();
 const detail:(string|number)[][]=[['รหัสพนักงาน','ชื่อ–นามสกุล','แผนก / งาน','ตำแหน่ง','ความต้องการ','ไซซ์เสื้อ','รอบอก (นิ้ว)','ความยาว (นิ้ว)','จำนวน (ตัว)','วันที่ตอบ (เวลาไทย)'],...results.map(r=>{const s=shirtSizes.find(s=>s.size===r.size);return [r.employee_id,r.name,r.department,r.position,r.need?'ต้องการ':'ไม่ต้องการ',r.size??'',s?.chest??'',s?.length??'',r.quantity,new Date(r.created_at).toLocaleString('th-TH',{timeZone:'Asia/Bangkok'})]})];
 const summary:(string|number)[][]=[['ไซซ์เสื้อ','รอบอก (นิ้ว)','ความยาว (นิ้ว)','จำนวน (ตัว)'],...shirtSizes.map(s=>[s.size,s.chest,s.length,results.filter(r=>r.need&&r.size===s.size).length]),['รวมเสื้อที่ต้องจัดหา','','',results.filter(r=>r.need).length],['ไม่ต้องการเสื้อกีฬา','','',results.filter(r=>!r.need).length],['พนักงานที่ตอบทั้งหมด','','',results.length]];
 return new Response(workbook([{name:'คำตอบพนักงาน',rows:detail},{name:'สรุปไซซ์เสื้อ',rows:summary}]),{headers:{'Content-Type':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','Content-Disposition':'attachment; filename="nam-phong-sports-survey.xlsx"','Cache-Control':'no-store'}});
 }catch(e){console.error(e);return Response.json({error:'ดาวน์โหลดไม่สำเร็จ กรุณาลองอีกครั้ง'},{status:503})}}

import { shirtSizes } from '../../../../lib/survey';
import { isAdmin, sameOrigin, unauthorized } from '../../../../lib/admin-auth';
import { surveyDb } from '../../../../lib/survey-db';
type Context={params:Promise<{id:string}>};
export async function PUT(request:Request,context:Context){
 try{
 if(!sameOrigin(request))return Response.json({error:'ไม่อนุญาตคำขอนี้'},{status:403});
 if(!await isAdmin(request))return unauthorized();
 const {id}=await context.params;
 const b=await request.json() as Record<string,unknown>;
 const str=(key:string,max:number)=>typeof b[key]==='string'?b[key].trim().slice(0,max):'';
 const employeeId=str('employeeId',30),name=str('name',120),department=str('department',100),position=str('position',100);
 if(!employeeId||!name||!department||!position||(b.need!=='yes'&&b.need!=='no'))return Response.json({error:'กรุณากรอกข้อมูลที่จำเป็นให้ครบ'},{status:400});
 const need=b.need==='yes',size=need?String(b.size??''):null,quantity=need?1:0;
 if(need&&(!shirtSizes.some(s=>s.size===size)))return Response.json({error:'กรุณาเลือกไซซ์เสื้อ SS–10XL'},{status:400});
 const row=await surveyDb().prepare('UPDATE responses SET employee_id=?,name=?,department=?,position=?,need=?,size=?,quantity=? WHERE id=? RETURNING id,employee_id,name,department,position,need,size,quantity,created_at').bind(employeeId,name,department,position,need?1:0,size,quantity,id).first();
 if(!row)return Response.json({error:'ไม่พบข้อมูลนี้ อาจถูกลบไปแล้ว กรุณาอัปเดตหน้าสรุป'},{status:404});
 return Response.json({ok:true,row},{headers:{'Cache-Control':'no-store'}});
 }catch(e){console.error(e);if(((e as {code?:string}).code==='23505'||String(e).includes('UNIQUE')))return Response.json({error:'รหัสพนักงานนี้มีคำตอบอื่นอยู่แล้ว กรุณาตรวจสอบรหัสอีกครั้ง'},{status:409});return Response.json({error:'แก้ไขไม่สำเร็จ ข้อมูลที่กรอกยังอยู่ กรุณาลองอีกครั้ง'},{status:503})}
}
export async function DELETE(request:Request,context:Context){
 try{
 if(!sameOrigin(request))return Response.json({error:'ไม่อนุญาตคำขอนี้'},{status:403});
 if(!await isAdmin(request))return unauthorized();
 const {id}=await context.params;
 const row=await surveyDb().prepare('DELETE FROM responses WHERE id=? RETURNING id').bind(id).first();
 if(!row)return Response.json({error:'ไม่พบข้อมูลนี้ อาจถูกลบไปแล้ว กรุณาอัปเดตหน้าสรุป'},{status:404});
 return Response.json({ok:true},{headers:{'Cache-Control':'no-store'}});
 }catch(e){console.error(e);return Response.json({error:'ลบไม่สำเร็จ กรุณาลองอีกครั้ง'},{status:503})}
}

import { shirtSizes } from '../../../lib/survey';
import { isAdmin, unauthorized } from '../../../lib/admin-auth';
import { surveyDb } from '../../../lib/survey-db';
export async function GET(request:Request) {
 try { if(!await isAdmin(request))return unauthorized(); const rows = await surveyDb().prepare('SELECT id,employee_id,name,department,position,need,size,CASE WHEN need=1 THEN 1 ELSE 0 END AS quantity,created_at FROM responses ORDER BY created_at DESC').all(); return Response.json({rows: rows.results}, {headers:{'Cache-Control':'no-store'}}); }
 catch(e) { console.error(e); return Response.json({error:'ยังโหลดข้อมูลไม่ได้ กรุณาลองอีกครั้ง'}, {status:503}); }
}
export async function POST(request:Request) {
 try {
 const b = await request.json() as Record<string,unknown>;
 const str=(key:string,max:number)=>typeof b[key]==='string'?b[key].trim().slice(0,max):'';
 const employeeId=str('employeeId',30), name=str('name',120), department=str('department',100), position=str('position',100);
 if(!employeeId||!name||!department||!position||(b.need!=='yes'&&b.need!=='no')) return Response.json({error:'กรุณากรอกข้อมูลที่จำเป็นให้ครบ'}, {status:400});
 const need=b.need==='yes', size=need?String(b.size??''):null, quantity=need?1:0;
 if(need&&(!shirtSizes.some(s=>s.size===size))) return Response.json({error:'กรุณาเลือกไซซ์เสื้อ SS–10XL'}, {status:400});
 await surveyDb().prepare('INSERT INTO responses (id,employee_id,name,department,position,need,size,quantity,note,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)').bind(crypto.randomUUID(),employeeId,name,department,position,need?1:0,size,quantity,'',new Date().toISOString()).run();
 return Response.json({ok:true},{status:201});
 } catch(e) { console.error(e); if(((e as {code?:string}).code==='23505'||String(e).includes('UNIQUE'))) return Response.json({error:'รหัสพนักงานนี้ส่งแบบสำรวจแล้ว กรุณาติดต่อผู้รวบรวมเพื่อแก้ไขข้อมูล'}, {status:409}); return Response.json({error:'บันทึกไม่สำเร็จ ข้อมูลที่กรอกยังอยู่ กรุณาลองอีกครั้ง'}, {status:503}); }
}

