'use client';
import { useEffect,useRef,useState,FormEvent } from 'react';
import { shirtSizes } from '../../lib/survey';
import { X,Check,Trash2 } from 'lucide-react';
export type SurveyRow={id:string;employee_id:string;name:string;department:string;position:string;need:number;size:string|null;quantity:number;created_at:string};
type Props={row:SurveyRow;mode:'edit'|'delete';onClose:()=>void;onSaved:(text:string)=>void;onExpired:()=>void};
export default function ResponseManager({row,mode,onClose,onSaved,onExpired}:Props){
 const dialog=useRef<HTMLDialogElement>(null),[need,setNeed]=useState(row.need?'yes':'no'),[busy,setBusy]=useState(false),[error,setError]=useState('');
 useEffect(()=>{dialog.current?.showModal();const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.body.style.overflow=old;dialog.current?.close()}},[]);
 async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();await mutate('PUT',Object.fromEntries(new FormData(e.currentTarget)))}
 async function mutate(method:'PUT'|'DELETE',body?:Record<string,FormDataEntryValue>){
 setBusy(true);setError('');try{const r=await fetch(`/api/responses/${encodeURIComponent(row.id)}`,{method,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});
 if(r.status===401){onExpired();return}const j=await r.json() as {error?:string};if(!r.ok)throw Error(j.error??'ดำเนินการไม่สำเร็จ');onSaved(method==='PUT'?'บันทึกการแก้ไขเรียบร้อยแล้ว':'ลบข้อมูลเรียบร้อยแล้ว');
 }catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 return <dialog ref={dialog} className={'manage-dialog '+(mode==='delete'?'delete-dialog':'')} aria-labelledby="manage-title" onCancel={e=>{e.preventDefault();if(!busy)onClose()}} onClick={e=>{if(e.target===e.currentTarget&&!busy)onClose()}}><div className="manage-head"><h2 id="manage-title">{mode==='edit'?'แก้ไขข้อมูลพนักงาน':'ยืนยันการลบข้อมูล'}</h2><button type="button" className="close-button" aria-label="ปิดหน้าจัดการข้อมูล" disabled={busy} onClick={onClose}><X size={22}/></button></div>
 {mode==='edit'?<form onSubmit={save}><p className="manage-description">จัดสรรเสื้อกีฬาคนละ 1 ตัว ช่องที่มี <b>*</b> จำเป็นต้องกรอก</p><div className="field-grid"><label>รหัสพนักงาน <b>*</b><input name="employeeId" defaultValue={row.employee_id} required maxLength={30} autoComplete="off"/></label><label>ชื่อ–นามสกุล <b>*</b><input name="name" defaultValue={row.name} required maxLength={120}/></label><label>แผนก / งาน <b>*</b><input name="department" defaultValue={row.department} required maxLength={100}/></label><label>ตำแหน่ง <b>*</b><input name="position" defaultValue={row.position} required maxLength={100}/></label></div><fieldset><legend>ความต้องการเสื้อกีฬา <b>*</b></legend><div className="choice-row">{[['yes','ต้องการเสื้อกีฬา'],['no','ไม่ต้องการ']].map(([v,t])=><label className={'choice '+(need===v?'selected':'')} key={v}><input type="radio" name="need" value={v} checked={need===v} onChange={()=>setNeed(v)}/>{t}</label>)}</div></fieldset>{need==='yes'&&<div className="field-grid"><label>ไซซ์เสื้อกีฬา <b>*</b><select name="size" defaultValue={row.size??''} required><option value="" disabled>เลือกไซซ์เสื้อกีฬา</option>{shirtSizes.map(s=><option key={s.size} value={s.size}>{s.size} · รอบอก {s.chest} นิ้ว · ยาว {s.length} นิ้ว</option>)}</select></label></div>}{error&&<div className="notice error" role="alert">{error}</div>}<div className="manage-footer"><button type="button" className="secondary" disabled={busy} onClick={onClose}>ยกเลิก</button><button type="submit" className="primary" disabled={busy}><Check size={18}/>{busy?'กำลังบันทึก…':'บันทึกการแก้ไข'}</button></div></form>:
 <><p className="manage-description">ต้องการลบคำตอบของพนักงานคนนี้หรือไม่?</p><div className="delete-person"><strong>{row.name}</strong><span>รหัสพนักงาน {row.employee_id}</span><span>{row.department} · {row.position}</span></div><p className="delete-warning">ข้อมูลนี้จะถูกลบออกจากผลสำรวจและไฟล์ Excel และไม่สามารถกู้คืนได้</p>{error&&<div className="notice error" role="alert">{error}</div>}<div className="manage-footer"><button type="button" className="secondary" disabled={busy} onClick={onClose} autoFocus>ยกเลิก</button><button type="button" className="danger-button" disabled={busy} onClick={()=>mutate('DELETE')}><Trash2 size={18}/>{busy?'กำลังลบ…':'ยืนยันลบข้อมูล'}</button></div></>}
 </dialog>;
}

import { surveyDb } from './survey-db';
const COOKIE='sports_admin_session';
export async function hash(s:string){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))).map(x=>x.toString(16).padStart(2,'0')).join('')}
export function sessionToken(request:Request){return request.headers.get('cookie')?.split(';').map(s=>s.trim()).find(s=>s.startsWith(COOKIE+'='))?.slice(COOKIE.length+1)??''}
export async function isAdmin(request:Request){const token=sessionToken(request);if(!/^[a-f0-9-]{36}$/.test(token))return false;return !!await surveyDb().prepare('SELECT token_hash FROM admin_sessions WHERE token_hash=? AND expires_at>?').bind(await hash(token),Date.now()).first()}
export function unauthorized(){return Response.json({error:'กรุณาใส่รหัสผ่านก่อนดูผลสำรวจ'},{status:401,headers:{'Cache-Control':'no-store'}})}
export function cookie(request:Request,token:string,seconds:number){return `${COOKIE}=${token}; Path=/; HttpOnly; SameSite=Strict; Max-Age=${seconds}${new URL(request.url).protocol==='https:'?'; Secure':''}`}
export function sameOrigin(request:Request){const origin=request.headers.get('origin');return !origin||origin===new URL(request.url).origin}

import { neon } from '@neondatabase/serverless';
type SqlValue=string|number|null;
const schemas=[
 `CREATE TABLE IF NOT EXISTS sports_responses (
 id TEXT PRIMARY KEY, employee_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL,
 department TEXT NOT NULL, position TEXT NOT NULL, need INTEGER NOT NULL CHECK(need IN (0,1)),
 size TEXT, quantity INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL,
 CHECK((need=1 AND quantity=1 AND size IS NOT NULL AND size IN ('SS','S','M','L','XL','2XL','3XL','4XL','5XL','6XL','7XL','8XL','9XL','10XL'))
 OR (need=0 AND quantity=0 AND size IS NULL)))`,
 'CREATE TABLE IF NOT EXISTS sports_admin_sessions (token_hash TEXT PRIMARY KEY, expires_at BIGINT NOT NULL)',
 'CREATE TABLE IF NOT EXISTS sports_pin_attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, window_start BIGINT NOT NULL)'
];
let setup:Promise<unknown>|undefined;
async function client(){
 const url=process.env.DATABASE_URL;
 if(!url)throw Error('DATABASE_URL is not configured');
 const sql=neon(url);
 // This Vercel edition provisions only its own sports_* tables, preserving the shoe survey.
 if(!setup)setup=sql.transaction(schemas.map(s=>sql.query(s,[]))).catch(error=>{setup=undefined;throw error});
 await setup;
 return sql;
}
class Statement {
 readonly text:string;
 constructor(text:string,readonly values:SqlValue[]=[]){
  let i=0;
  this.text=text.replace(/\b(responses|admin_sessions|pin_attempts)\b/g,'sports_$1').replace(/\?/g,()=>`$${++i}`);
 }
 bind(...values:SqlValue[]){return new Statement(this.text,values)}
 async all<T=Record<string,unknown>>(){const sql=await client();return {results:await sql.query(this.text,this.values) as T[]}}
 async first<T=Record<string,unknown>>(){return (await this.all<T>()).results[0]??null}
 async run(){await this.all();return {success:true}}
}
export function surveyDb(){return {
 prepare:(text:string)=>new Statement(text),
 batch:async(statements:Statement[])=>{const sql=await client();return sql.transaction(statements.map(s=>sql.query(s.text,s.values)))}
}}

// Small OOXML writer: stored ZIP entries, inline strings, numeric quantities.
const encode=new TextEncoder();
const xml=(s:unknown)=>String(s??'').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g,'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]!));
function crc32(bytes:Uint8Array){let c=0xffffffff;for(const b of bytes){c^=b;for(let j=0;j<8;j++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^0xffffffff)>>>0}
function join(parts:Uint8Array[]){const out=new Uint8Array(parts.reduce((s,p)=>s+p.length,0));let n=0;for(const p of parts){out.set(p,n);n+=p.length}return out}
function zip(files:Record<string,string>){const parts:Uint8Array[]=[],central:Uint8Array[]=[];let offset=0;for(const [name,value] of Object.entries(files)){const n=encode.encode(name),d=encode.encode(value),crc=crc32(d),h=new Uint8Array(30),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,33,true);v.setUint32(14,crc,true);v.setUint32(18,d.length,true);v.setUint32(22,d.length,true);v.setUint16(26,n.length,true);parts.push(h,n,d);const c=new Uint8Array(46),w=new DataView(c.buffer);w.setUint32(0,0x02014b50,true);w.setUint16(4,20,true);w.setUint16(6,20,true);w.setUint16(8,0x800,true);w.setUint16(14,33,true);w.setUint32(16,crc,true);w.setUint32(20,d.length,true);w.setUint32(24,d.length,true);w.setUint16(28,n.length,true);w.setUint32(42,offset,true);central.push(c,n);offset+=h.length+n.length+d.length}const cd=join(central),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,Object.keys(files).length,true);v.setUint16(10,Object.keys(files).length,true);v.setUint32(12,cd.length,true);v.setUint32(16,offset,true);return join([...parts,cd,end])}
export function workbook(sheets:{name:string;rows:(string|number)[][]}[]){const files:Record<string,string>={};files['[Content_Types].xml']=`<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`;
files['_rels/.rels']='<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>';
files['xl/workbook.xml']=`<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.map((s,i)=>`<sheet name="${xml(s.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`;
files['xl/_rels/workbook.xml.rels']=`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}</Relationships>`;
for(const [i,s] of sheets.entries()){files[`xl/worksheets/sheet${i+1}.xml`]=`<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" state="frozen"/></sheetView></sheetViews><cols>${s.rows[0].map((_,j)=>`<col min="${j+1}" max="${j+1}" width="${j===0?18:28}" customWidth="1"/>`).join('')}</cols><sheetData>${s.rows.map((r,j)=>`<row r="${j+1}">${r.map((v,k)=>{const ref=String.fromCharCode(65+k)+(j+1);return typeof v==='number'?`<c r="${ref}"><v>${v}</v></c>`:`<c r="${ref}" t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`}).join('')}</row>`).join('')}</sheetData><autoFilter ref="A1:${String.fromCharCode(64+s.rows[0].length)}${s.rows.length}"/></worksheet>`}return zip(files)}
